from .ir import Step,StepSortKey
PHASE_ORDER={"FINDING":0,"REMEDIATION":1,"VERIFICATION":2}
OPERATION_ORDER={"REPORT_REMAINING_RECORD":0,"REPORT_EXPOSED_PII":1,"REPORT_ACTIVE_DATA_FLOW":2,"REPORT_RESTORE_RISK":3,"DISABLE_DATA_FLOW":10,"BLOCK_RESTORE":11,"DELETE_RECORD":12,"REDACT_RECORD":13,"ANONYMIZE_RECORD":14,"VERIFY_RECORD_ABSENT":20,"VERIFY_RECORD_PRESENT":21,"VERIFY_RECORD_REDACTED":22,"VERIFY_RECORD_ANONYMIZED":23,"VERIFY_DATA_FLOW_DISABLED":24,"VERIFY_RESTORE_BLOCKED":25}
ALLOWED_STATE={"REPORT_REMAINING_RECORD":"PRESENT","REPORT_EXPOSED_PII":"PRESENT","REPORT_ACTIVE_DATA_FLOW":"ACTIVE","REPORT_RESTORE_RISK":"ACTIVE","DISABLE_DATA_FLOW":"DISABLED","BLOCK_RESTORE":"BLOCKED","DELETE_RECORD":"ABSENT","REDACT_RECORD":"REDACTED","ANONYMIZE_RECORD":"ANONYMIZED","VERIFY_RECORD_ABSENT":"ABSENT","VERIFY_RECORD_PRESENT":"PRESENT","VERIFY_RECORD_REDACTED":"REDACTED","VERIFY_RECORD_ANONYMIZED":"ANONYMIZED","VERIFY_DATA_FLOW_DISABLED":"DISABLED","VERIFY_RESTORE_BLOCKED":"BLOCKED"}
def _key(s): return StepSortKey(PHASE_ORDER[s.phase],OPERATION_ORDER[s.operation],s.system_id,s.resource_id)
def sort_steps(steps):
 for s in steps:
  if s.phase not in PHASE_ORDER or s.operation not in OPERATION_ORDER or ALLOWED_STATE[s.operation]!=s.state: raise ValueError(f"invalid step: {s}")
 ordered=sorted(steps,key=_key)
 for i,s in enumerate(ordered,1):s.step_no=i
 return ordered
